import React from 'react';

import { getWorkoutTypeColor } from '@apps/Workouts/@helpers/workouts.helper';
import { IWorkout } from '@apps/Workouts/@types/workouts.types';
import ActivitiesChart from '@components/ActivitiesChart';
import { getISODay } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';

interface IActivitiesYearChartProps {
  activities: IWorkout[];
  onDateClick: (date: Date) => void;
  d1?: Date;
  d2?: Date;
}

const ActivitiesYearChart = ({ activities, onDateClick, d1, d2 }: IActivitiesYearChartProps) => {
  let minDate = d1;
  let maxDate = d2;

  const maxDistanceForType: { [idActivityType: number]: number } = {};

  const daysContentMap = activities.reduce<{ [isoDate: string]: IWorkout[] }>((acc, activity) => {
    if (!minDate || activity.date_start < minDate) minDate = activity.date_start;
    if (!maxDate || activity.date_finish > maxDate) maxDate = activity.date_finish;
    if (!maxDistanceForType[activity.type.id])
      maxDistanceForType[activity.type.id] = activity.distance;

    if (maxDistanceForType[activity.type.id] < activity.distance)
      maxDistanceForType[activity.type.id] = activity.distance;

    console.warn(activity);

    const isoStart = getISODay(activity.date_start);

    if (!acc[isoStart]) acc[isoStart] = [];

    acc[isoStart].push(activity);

    return acc;
  }, {});

  return (
    <ActivitiesChart
      dayContentMap={Object.entries(daysContentMap).reduce<{ [isoDate: string]: React.ReactNode }>(
        (acc, [isoDay, workoutsList]) => {
          acc[isoDay] = (
            <div
              className="d-flex h-100 mt-auto"
              style={{ gap: 1 }}
              title={workoutsList
                .map((w) => [w.type.name, formatDistance(w.distance)].join('\t'))
                .join('\n')}
            >
              {workoutsList.map((w) => {
                return (
                  <div
                    key={w.id}
                    style={{
                      backgroundColor: getWorkoutTypeColor(w.type.id),
                      flexGrow: 1,
                      borderRadius: 3,
                      opacity: 0.2 + w.distance / maxDistanceForType[w.type.id],
                    }}
                  />
                );
              })}
            </div>
          );
          return acc;
        },
        {},
      )}
      onDayClick={onDateClick}
      d1={minDate!}
      d2={maxDate!}
    />
  );
};

export default ActivitiesYearChart;
